j.push(A.d(g,g,g,g,g,g,g,g,g,g,'\n\u041f\u0435\u0440\u0448\u0430\u044f \u043f\u0430\u043b\u043e\u0432\u0430 \u0441\u0430\u043a\u0430\u0432\u0456\u043a\u0430, \u0437\u0434\u0430\u0435\u0446\u0446\u0430, \u043f\u0440\u0430\u0439\u0448\u043b\u0430 \u045e \u0430\u0434\u0447\u0443\u0432\u0430\u043d\u043d\u0456 \u0441\u0432\u0430\u0451\u0439 \u0443\u043b\u0430\u0441\u043d\u0430\u0439 \u0431\u0435\u0437\u0434\u0430\u043f\u0430\u043c\u043e\u0436\u043d\u0430\u0441\u0446\u0456. \u042f \u043d\u0456\u044f\u043a \u043d\u0435 \u043c\u043e\u0433 \u0437\u043d\u0430\u0439\u0441\u0446\u0456 \u0441\u0432\u043e\u0439 \u0441\u043f\u043e\u0441\u0430\u0431, \u044f\u043a \u0434\u0430\u043f\u0430\u043c\u0430\u0433\u0447\u044b \u0423\u043a\u0440\u0430\u0456\u043d\u0435 \u0437\u043c\u0430\u0433\u0430\u0446\u0446\u0430 \u0437 \u043d\u0430\u043f\u0430\u0434\u0430\u043c \u0420\u0430\u0441\u0456\u0456. \u0411\u044b\u043b\u0456 \u0434\u0443\u043c\u043a\u0456 \u045e\u0437\u044f\u0446\u0446\u0430 \u0437\u0430 \u0437\u0431\u0440\u043e\u044e, \u0430\u043b\u0435 \u044f \u0437\u0440\u0430\u0437\u0443\u043c\u0435\u045e, \u0448\u0442\u043e \u0433\u044d\u0442\u0430 \u043d\u0435 \u043c\u043e\u0439 \u0432\u0430\u0440\u044b\u044f\u043d\u0442 \u043d\u0456 \u043f\u0430 \u0436\u044b\u0446\u0446\u0451\u0432\u044b\u043c \u043f\u0440\u044b\u043d\u0446\u044b\u043f\u0430\u043c \u043d\u0456 \u043f\u0430 \u045e\u043b\u0430\u0441\u043d\u044b\u043c \u0444\u0456\u0437\u0456\u0447\u043d\u044b\u043c \u0441\u0442\u0430\u043d\u0435. \u0417\u043d\u043e\u045e \u0456 \u0437\u043d\u043e\u045e \u043f\u0440\u0430\u0432\u044f\u0440\u0430\u045e \u043d\u0430\u0432\u0456\u043d\u044b \u045e \u043d\u0430\u0434\u0437\u0435\u0456, \u0448\u0442\u043e \u043d\u0435\u0448\u0442\u0430 \u043d\u0430\u0440\u044d\u0448\u0446\u0435 \u043f\u0430\u0447\u0430\u043b\u043e \u043c\u044f\u043d\u044f\u0446\u0446\u0430 \u045e \u043b\u0435\u043f\u0448\u044b \u0431\u043e\u043a. \u0427\u0430\u043a\u0430\u045e "\u0446\u0443\u0434", \u0430 "\u0446\u0443\u0434" \u0443\u0441\u0451 \u043d\u0456\u044f\u043a \u043d\u0435 \u0430\u0434\u0431\u044b\u0432\u0430\u045e\u0441\u044f. \u0420\u0430\u0441\u0456\u044f\u043d\u0435 \u043c\u043e\u0446\u043d\u0430 \u043d\u0435 \u043f\u0430\u045e\u0441\u0442\u0430\u043b\u0456. \u0420\u0430\u0441\u0456\u0439\u0441\u043a\u0456\u044f \u0432\u0430\u0439\u0441\u043a\u043e\u045e\u0446\u044b \u0437\u0431\u0440\u043e\u044e \u043d\u0435 \u043f\u0430\u0432\u044f\u0440\u043d\u0443\u043b\u0456.\n\n\u0422\u0430\u043a\u0441\u0430\u043c\u0430 \u0431\u044b\u043b\u043e \u043c\u043e\u0446\u043d\u0430\u0435 \u0436\u0430\u0434\u0430\u043d\u043d\u0435 \u045e\u0432\u0435\u0437\u0446\u0456 \u0441\u0432\u0430\u0456\u0445 \u0434\u0437\u044f\u0446\u0435\u0439 \u0437 \u0411\u0435\u043b\u0430\u0440\u0443\u0441\u0456. \u0410\u043b\u0435 \u0431\u044b\u043b\u0430\u044f \u0436\u043e\u043d\u043a\u0430 \u0431\u044b\u043b\u0430 \u043a\u0430\u0442\u044d\u0433\u0430\u0440\u044b\u0447\u043d\u0430 \u0441\u0443\u043f\u0440\u0430\u0446\u044c \u2014 "\u0411\u0435\u043b\u0430\u0440\u0443\u0441\u044c \u043d\u0456\u043a\u043e\u043b\u0456 \u043d\u0435 \u043f\u0435\u0440\u0430\u0442\u0432\u043e\u0440\u044b\u0446\u0446\u0430 \u045e \u041f\u0430\u045e\u043d\u043e\u0447\u043d\u0443\u044e \u041a\u0430\u0440\u044d\u044e". \u0410 \u044f \u0433\u044d\u0442\u0430 \u0440\u0430\u0437\u0443\u043c\u0435\u045e \u0442\u0430\u043a \u2014 "\u041d\u044f\u043c\u0430 \u043d\u0430 \u0441\u0432\u0435\u0446\u0435 \u043d\u0456\u0447\u043e\u0433\u0430 \u0431\u043e\u043b\u044c\u0448 \u0436\u0443\u0434\u0430\u0441\u043d\u0430\u0433\u0430, \u0447\u044b\u043c \u043f\u0435\u0440\u0430\u0435\u0437\u0434. \u041b\u0435\u043f\u0435\u0439 \u0431\u044b\u0446\u044c \u0443 \u043a\u0430\u043d\u0446\u043b\u0430\u0433\u0435\u0440\u044b, \u0447\u044b\u043c \u043d\u0435\u043a\u0443\u0434\u044b \u043f\u0435\u0440\u0430\u0435\u0445\u0430\u0446\u044c."\n\n\u0410\u0434\u043d\u044b\u043c \u0441\u043b\u043e\u0432\u0430\u043c \u2014 \u0431\u0435\u0437\u0434\u0430\u043f\u0430\u043c\u043e\u0436\u043d\u0430\u0441\u0446\u044c \u0430\u0434\u043d\u0430\u0447\u0430\u0441\u043e\u0432\u0430 \u0437 \u043d\u0435\u043a\u0430\u043b\u044c\u043a\u0456\u0445 \u0432\u0430\u0436\u043d\u044b\u0445 \u0431\u0430\u043a\u043e\u045e.\n\n\u0410\u0434\u0437\u0456\u043d\u0430\u0435, \u0448\u0442\u043e \u043f\u0440\u044b\u0439\u0448\u043b\u043e \u043c\u043d\u0435 \u045e \u0433\u0430\u043b\u0430\u0432\u0443 \u2014 \u043a\u0430\u043b\u0456 \u0433\u0440\u043e\u0448\u044b \u0437 \u0431\u044e\u0434\u0436\u044d\u0442\u0430 \u0411\u0435\u043b\u0430\u0440\u0443\u0441\u0456 \u0446\u0456, \u043d\u0430\u043f\u0440\u044b\u043a\u043b\u0430\u0434, \u043f\u0430\u043b\u0456\u0432\u0430 \u0442\u0440\u0430\u0446\u044f\u0446\u0446\u0430 \u043d\u0430 \u043c\u0456\u0440\u043d\u044b\u044f \u0440\u044d\u0447\u044b, \u0442\u043e \u044f\u043d\u044b \u0434\u0430\u043a\u043b\u0430\u0434\u043d\u0430 \u043d\u0435 \u0442\u0440\u0430\u0446\u044f\u0446\u0446\u0430 \u043d\u0430 \u043a\u0430\u0440\u043d\u0456\u043a\u0430\u045e \u0456 \u043d\u0430 \u043f\u0430\u0434\u0442\u0440\u044b\u043c\u043a\u0443 \u0432\u0430\u0439\u043d\u044b. \u0406 10 \u0441\u0430\u043a\u0430\u0432\u0456\u043a\u0430 \u0441\u0442\u0432\u0430\u0440\u044b\u045e 9 \u0437\u0430\u044f\u0432\u0430\u043a \u0443 115.\u0431\u0435\u043b. \u0410\u0434\u043d\u0430 \u043c\u0430\u044f \u0441\u0443\u0440\u0430\u0437\u043c\u043e\u045e\u0446\u0430 \u0442\u0430\u0434\u044b \u043a\u0430\u0437\u0430\u043b\u0430 \u043c\u043d\u0435, \u0448\u0442\u043e \u043d\u0430 \u043a\u0430\u0440\u043d\u0456\u043a\u0430\u045e \u0433\u0440\u043e\u0448\u044b \u0437\u0430\u045e\u0441\u0451\u0434\u044b \u0437\u043d\u043e\u0439\u0434\u0443\u0446\u0446\u0430. \u041d\u0443\u2026 \u041d\u0430\u043f\u044d\u045e\u043d\u0430, \u0433\u044d\u0442\u0430 \u0442\u0430\u043a\u2026 \u0410\u043b\u0435 \u043f\u0430\u043a\u043e\u043b\u044c\u043a\u0456 \u0430\u043b\u044c\u0442\u044d\u0440\u043d\u0430\u0442\u044b\u0432\u044b \u043d\u0435 \u0431\u044b\u043b\u043e \u043f\u0440\u0430\u043f\u0430\u043d\u0430\u0432\u0430\u043d\u0430, \u0442\u043e \u0432\u044b\u0440\u0430\u0448\u044b\u045e, \u0448\u0442\u043e \u043b\u0435\u043f\u0435\u0439 \u0440\u0430\u0431\u0456\u0446\u044c \u043d\u0435\u0448\u0442\u0430, \u0447\u044b\u043c \u0437\u0443\u0441\u0456\u043c \u043d\u0456\u0447\u043e\u0433\u0430.\n'))
j.push(A.d(g,g,g,g,g,g,g,g,g,B.t,"\n\n\u0414\u0440\u0443\u0433\u0430\u044f \u043f\u0430\u043b\u043e\u0432\u0430 \u0441\u0430\u043a\u0430\u0432\u0456\u043a\u0430 2022 \u0433\u043e\u0434\u0430.\n"))
